from pathlib import Path
from html import escape
root=Path(__file__).resolve().parent
origin='https://pranav108.github.io/ShadeLab'
base_path='/ShadeLab/'
email='pranvcoder@gmail.com'
def page(title,desc,path,content,active='',kind=''):
 nav=''.join(f'<a {"class=game-link" if label=="The game" else ""} href="{href}" {"aria-current=page" if active==label else ""}>{label}</a>' for label,href in [('The game','/#play'),('Support','/support/'),('Privacy','/privacy/')])
 return f'''<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta name="theme-color" content="#b9a9dc"><title>{escape(title)}</title><meta name="description" content="{escape(desc)}"><link rel="canonical" href="{origin}{path}"><meta property="og:title" content="{escape(title)}"><meta property="og:description" content="{escape(desc)}"><meta property="og:type" content="website"><meta property="og:url" content="{origin}{path}"><meta property="og:image" content="{origin}/assets/icon.png"><link rel="icon" type="image/png" href="/assets/icon.png"><link rel="apple-touch-icon" href="/assets/icon.png"><link rel="stylesheet" href="/styles.css"><link rel="preload" href="/assets/nunito.ttf" as="font" type="font/ttf" crossorigin></head><body class="{kind}"><a class="skip" href="#main">Skip to content</a><header class="header wrap"><a class="brand" href="/" aria-label="ShadeLab home"><img src="/assets/icon.png" width="48" height="48" alt=""><span>ShadeLab</span></a><nav class="nav" aria-label="Main navigation">{nav}</nav></header>{content}<footer class="footer"><div class="wrap"><div class="footer-grid"><div><a class="brand" href="/">ShadeLab</a><p>A little color. A clear mind.</p></div><div class="footer-links"><a href="/support/">Support</a><a href="/privacy/">Privacy policy</a><a href="mailto:{email}">Contact</a></div></div><p class="footer-small">Questions? <a href="mailto:{email}">{email}</a></p></div></footer></body></html>'''.replace('href="/', f'href="{base_path}').replace('src="/', f'src="{base_path}')
home='''<main id="main"><section class="hero"><div class="wrap hero-grid"><div class="hero-copy"><h1>A little color.<br>A clear mind.</h1><p>Find a little calm in every pour. Sort shimmering layers, fill the right orders, and give every color a place to settle.</p><div class="actions"><a class="button" href="#play">Explore the game</a><a class="button secondary" href="#how-to-play">How to play</a></div></div><div class="hero-art"><img src="/assets/icon.png" width="1024" height="1024" alt="Three glass bottles filled with mint, coral and purple liquid" fetchpriority="high"></div></div><svg class="hero-wave" viewBox="0 0 1440 85" preserveAspectRatio="none" aria-hidden="true"><path d="M0 38C240 108 370-12 635 37S1160 108 1440 22V85H0Z" fill="#a4d5c7"/></svg></section><section class="intro" id="play"><div class="wrap"><div class="intro-grid"><h2>One thoughtful<br>pour at a time.</h2><p>Each bottle holds four layers. Move matching colors together, seal a finished bottle, and watch it pack into its matching order. New orders and covered bottles give you something more to think about as you go.</p></div><div class="quiet-facts"><span>50 levels to explore</span><span>iPhone &amp; iPad</span><span>No account needed</span></div></div></section><section class="screens"><div class="wrap"><div class="section-head"><h2>A small world<br>full of color.</h2><p>From the first pour to the trickier layers, take the journey at your own pace.</p></div><div class="gallery" aria-label="Actual ShadeLab game screenshots"><figure><img src="/assets/gameplay.png" width="1206" height="2622" alt="ShadeLab level 12 with layered bottles and active color orders" loading="lazy"><figcaption><h3>Sort your colors</h3><p>Read the layers. Find a match. Make room for your next move.</p></figcaption></figure><figure><img src="/assets/journey.png" width="1206" height="2622" alt="Journey screen showing completed, current and locked stages" loading="lazy"><figcaption><h3>Follow your journey</h3><p>Build your progress across 50 levels, and revisit completed puzzles.</p></figcaption></figure><figure><img src="/assets/covered.png" width="1206" height="2622" alt="Level 26 with a covered bottle that unlocks after a new bottle is completed" loading="lazy"><figcaption><h3>Uncover the next layer</h3><p>Complete bottles to reveal covered ones and open up new possibilities.</p></figcaption></figure></div></div></section><section class="how" id="how-to-play"><div class="wrap"><div class="how-grid"><h2>A simple start.<br>Room to think.</h2><ol class="steps"><li><div><h3>Choose your bottle</h3><p>Tap a source, then an empty bottle or one with the same color on top. Matching top layers pour together, up to the space available.</p></div></li><li><div><h3>Bring a color together</h3><p>Four matching layers seal a bottle. It packs when a matching order is active; otherwise it waits safely sealed.</p></div></li><li><div><h3>Make your next move</h3><p>Keep an eye on the next order. Use Undo when you want to rethink a pour, or pause and return later.</p></div></li></ol></div><div class="comfort"><div><h3>Make yourself comfortable</h3><p>Choose sound, music and haptics. Turn on reduced motion or use color symbols to help distinguish the layers.</p></div><div><h3>Your progress stays with you</h3><p>Your puzzle and settings are saved on your device. No account is needed to play. <a href="/privacy/">Read our privacy policy</a>.</p></div></div></div></section></main>'''
(root/'index.html').write_text(page('ShadeLab — A little color. A clear mind.','A calm color-sorting puzzle for iPhone and iPad. Explore 50 levels of glass bottles, layered colors and thoughtful pours.','/',home,'The game'))
sections=[('Who this policy covers',f'This policy explains how ShadeLab handles information in the game and on this website. The operator is the ShadeLab developer. For privacy questions or requests, email <a href="mailto:{email}">{email}</a>.'),('Game progress and settings','ShadeLab stores your puzzle state, completed levels, undo history, tutorial progress, navigation state and preferences on your device. Preferences include sound, music, haptics, reduced motion and color symbols. These files let you continue where you left off. You do not need to create an account, and we do not run a server that receives or synchronizes your game progress.'),('Advertising, analytics and permissions','The current game does not integrate an advertising service, advertising identifier tracking, in-app purchases or developer-configured behavioral analytics. Unity cloud analytics, advertising and cloud diagnostics services are disabled in the current project. The game does not request access to your camera, microphone, contacts, photos or location.'),('Apple and device services','ShadeLab is built with Unity and runs on Apple devices. Apple may separately process App Store transactions, installation information or device diagnostics according to your device settings and its own privacy policy. Device backups may include locally stored game files, depending on your Apple backup settings. ShadeLab does not operate its own cloud-save or account service. <a href="https://www.apple.com/legal/privacy/">Read Apple’s privacy information</a>.'),('When you contact us',f'If you email <a href="mailto:{email}">{email}</a>, we receive your email address, your message and any details you choose to include. We use that information to respond to your request and provide support. Please do not send passwords, payment details or other sensitive information. Email is handled through our email provider, Google, under its <a href="https://policies.google.com/privacy">privacy policy</a>.'),('This website','This website does not add advertising trackers, audience analytics, contact forms or visitor accounts. Fonts and game artwork are served with the website rather than loaded from third-party font services. GitHub Pages and its infrastructure providers may process technical request information, such as IP address, browser information, request time and URL, to deliver and protect the site. Essential platform or security cookies may be used by the hosting provider. We do not add marketing cookies or use website requests to track your gameplay. See the <a href="https://docs.github.com/en/site-policy/privacy-policies/github-general-privacy-statement">GitHub Privacy Statement</a> for hosting-provider information.'),('Sharing and sale','We do not sell your personal information or share it for targeted advertising. Information you send by email is handled by the email service used to deliver and respond to your message. Technical website requests are handled by hosting and security providers. Information may also be disclosed when required by law or necessary to address misuse or security incidents.'),('Retention and deletion','Game progress and preferences stay on your device until the app’s stored data is removed. On iPhone or iPad, deleting the app removes its local app data; offloading the app may retain it. Copies in device backups are controlled through your Apple backup settings and may remain after app deletion. We cannot retrieve or delete local game files remotely. We keep support correspondence only as long as needed to address the request and meet applicable legal or security needs. You can email us to request deletion of support correspondence. Hosting providers apply their own operational and security retention practices.'),('Your choices and requests',f'You can play without registering or sending us personal information. You can change game preferences in Settings, manage device diagnostics and backups through Apple settings, and remove local game data by deleting the app. To ask about information you sent us, request access or correction, or request deletion of support correspondence, contact <a href="mailto:{email}">{email}</a>. We will respond in accordance with applicable law and may need to verify that a request concerns your own information.'),('Children’s privacy','The game does not require players, including children, to submit personal information or create an account. We do not knowingly ask children to provide personal information through the game. If you believe a child has sent personal information to us by email, please contact us so we can address the request and delete it as appropriate.'),('Changes to this policy','We may update this policy if the game, website or our data practices change. The date at the top of this page identifies the latest revision. Changes that require permission will be handled before the relevant collection or use begins.'),('Contact',f'For ShadeLab support and privacy matters: <a href="mailto:{email}">{email}</a>.')]
policy='<main class="article-main wrap" id="main"><div class="article-head"><h1>Privacy policy</h1><p>Room for color. Respect for your information.</p><p class="date">Effective and last updated: 20 November 2026</p></div><article class="paper"><div class="summary"><strong>The short version</strong><p>Your game progress and settings are stored on your device. No account is needed. If you contact us, we use your message to help you. Website hosting involves the technical information needed to serve and protect these pages.</p></div>'+''.join(f'<section><h2>{h}</h2><p>{body}</p></section>' for h,body in sections)+'</article></main>'
(root/'privacy/index.html').write_text(page('Privacy policy — ShadeLab','How ShadeLab handles local game data, support messages and website requests. Contact the developer about your privacy.','/privacy/',policy,'Privacy'))
faqs=[('How do I pour?','Tap a source bottle, then an empty bottle or one with a matching top color. The game pours consecutive matching top layers into the available space.'),('Why is a finished bottle waiting?','A sealed bottle packs when its color matches an active order. Check the next-order preview and continue sorting until that color reaches an active slot.'),('What does Undo restore?','Undo reverses the previous pour and its connected sealing, packing and unlock changes together.'),('How do I reveal a covered bottle?','Complete the number of new bottles shown on its cover. The cover’s counter decreases as you make those completions.'),('Can I come back to my puzzle later?','Yes. Your current puzzle and preferences are saved locally. Use Save and exit from the pause menu when you want to take a break.'),('Can I play without relying only on color?','Color symbols are available in Settings. You can also choose reduced motion, and adjust sound, music and haptics.'),('Does ShadeLab sync between devices?','ShadeLab does not have an account or its own cloud-sync service. Progress is stored on the device where you play. Apple device backups may behave according to your backup settings.'),('How do I report a problem?',f'Email <a href="mailto:{email}">{email}</a> with your device model, iOS version, level number and a short description. A screenshot can help. Please avoid including sensitive information.')]
support='<main class="article-main wrap" id="main"><div class="article-head"><h1>A little help.</h1><p>Stuck on a rule, or something not quite right? Let’s get you back to your next pour.</p></div><article class="paper"><div class="summary"><h2>Talk to the developer</h2><p><a href="mailto:'+email+'">'+email+'</a></p><p>Include your device model, iOS version and level number when reporting an issue.</p></div><section><h2>Common questions</h2>'+''.join(f'<details><summary>{q}</summary><p>{a}</p></details>' for q,a in faqs)+'</section><section><h2>Privacy questions</h2><p>See our <a href="/privacy/">privacy policy</a> for local saves, deleting data and contacting us about information you’ve shared.</p></section></article></main>'
(root/'support/index.html').write_text(page('Support — ShadeLab','ShadeLab game support, common questions and contact information.','/support/',support,'Support'))
(root/'404.html').write_text(page('Page not found — ShadeLab','Find your way back to ShadeLab.','/404.html','<main id="main" class="article-main wrap"><div class="article-head"><h1>A different path.</h1><p>That page isn’t here. You can return to the game overview or find the policy below.</p><div class="actions" style="margin-top:30px"><a class="button" href="/">ShadeLab home</a><a class="button secondary" href="/privacy/">Privacy policy</a></div></div></main>',kind='error'))
(root/'robots.txt').write_text('User-agent: *\nAllow: /\nSitemap: '+origin+'/sitemap.xml\n')
(root/'sitemap.xml').write_text('<?xml version="1.0" encoding="UTF-8"?><urlset xmlns="http://www.sitemaps.org/schemas/sitemap/0.9">'+''.join(f'<url><loc>{origin}{path}</loc><lastmod>2026-11-20</lastmod></url>' for path in ['/','/privacy/','/support/'])+'</urlset>')
print('Built GitHub Pages homepage, privacy, support,404 and metadata')
